#[test]
fn deduplication_window_does_not_slide_and_reopens_after_300_seconds() {
    let dup = json!({"Command": "SendMessage", "QueueName": "f.fifo", "Body": "b", "GroupId": "g", "DeduplicationId": "k"});
    let responses = run_values(&[
        create("f.fifo", json!({"Fifo": true})),
        dup.clone(),
        tick(200),
        dup.clone(),
        tick(100),
        dup.clone(),
        tick(299),
        dup.clone(),
        tick(1),
        dup,
    ]);
    // t=0 accepted; t=200 duplicate (does not extend); t=300 accepted anew;
    // t=599 duplicate of the second; t=600 accepted anew.
    let ids: Vec<_> = [1, 3, 5, 7, 9].iter().map(|&i| responses[i]["MessageId"].clone()).collect();
    assert_eq!(ids, [json!("m-1"), json!("m-1"), json!("m-2"), json!("m-2"), json!("m-3")]);
    let sequences: Vec<_> = [1, 3, 5, 7, 9].iter().map(|&i| responses[i]["SequenceNumber"].clone()).collect();
    assert_eq!(sequences, [json!(1), json!(1), json!(2), json!(2), json!(3)]);
}

